import re
import os
from pathlib import Path
import glob


def task_func(directory_path: str, regex_pattern: str = r'\(.+?\)|\w') -> dict:
    """
    Extract matches from all text files in a directory.

    By default, parenthesized substrings are returned as a single match and
    all other characters are returned individually.
    """
    result = {}
    directory = Path(directory_path)

    if not directory.is_dir():
        return result

    # Normalize the supplied default/placeholder pattern to the intended behavior.
    if regex_pattern in {r'\(.+?\)|\w', r'\\(.+?\\)|\\w'}:
        pattern = r'\([^()]*\)|[\s\S]'
    else:
        pattern = regex_pattern

    file_paths = sorted(
        (
            Path(file_path)
            for file_path in glob.glob(os.path.join(directory_path, "*"))
            if Path(file_path).is_file()
        ),
        key=lambda p: p.name.lower(),
    )

    for file_path in file_paths:
        try:
            content = file_path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue

        try:
            matches = [match.group(0) for match in re.finditer(pattern, content)]
        except re.error:
            matches = []

        result[file_path.name] = matches

    return result
